// Roamvas service worker — deliberately hand-written rather than generated by a
// build plugin. The build emits precache.json (see vite.config.ts) — the list
// of this release's hashed JS/CSS files — and the worker caches those at
// install, so a plan opens without a network even on a screen that has never
// been visited. The trip data itself already lives in localStorage.
//
// Bump this on any change that should force clients to pick up a fresh
// cache (e.g. after a deploy where old cached assets could otherwise linger).
//
// v2 (25.10.2026): страница (index.html) теперь берётся сначала из сети —
// см. fetch ниже. Смена имени заодно один раз выбрасывает накопившиеся
// бандлы всех прошлых сборок.
const CACHE_NAME = 'roamvas-cache-v2';
// Тайлы карты и фото мест — отдельно: их много, и у них свой предел.
const MEDIA_CACHE = 'roamvas-media-v1';
const MEDIA_CACHE_LIMIT = 1500;

// Картинки с этих адресов кешируются по мере просмотра (не заранее:
// правила OpenStreetMap запрещают выкачивать тайлы впрок, но разрешают
// хранить уже показанные). Все три отвечают с CORS — воркер запрашивает
// их сам в режиме cors: «непрозрачный» ответ обычного <img> Chrome
// засчитывает в квоту как ~7 МБ, тысяча тайлов съела бы гигабайты.
// Фото по ссылке, вставленной вручную, сюда не попадает — чужой сервер
// может не отвечать с CORS.
const MEDIA_HOSTS = /^(?:[abc]\.)?tile\.openstreetmap\.org$|^upload\.wikimedia\.org$|^media\.roamvas\.app$/;

// Пауза перед докачкой: воркер ставится сразу после загрузки страницы, а
// после выкладки та в это время ещё тянет свои новые файлы (через прежний
// воркер, в этот же кеш). Без паузы оба качали одно и то же наперегонки —
// на медленной сети файлы приходили дважды. Через 5 с то, что страница
// уже взяла, лежит в кеше, и докачка его пропускает.
const PRECACHE_DELAY_MS = 5000;

async function precache() {
  // Экономия трафика в браузере — заранее ничего не качаем.
  if (self.navigator && self.navigator.connection && self.navigator.connection.saveData) return;
  await new Promise((resolve) => setTimeout(resolve, PRECACHE_DELAY_MS));
  const cache = await caches.open(CACHE_NAME);
  await cache.addAll(['./', './index.html']).catch(() => {});
  const res = await fetch('./precache.json', { cache: 'no-cache' });
  if (!res.ok) return;
  const { files } = await res.json();
  await cache.put('./precache.json', new Response(JSON.stringify({ files }), { headers: { 'Content-Type': 'application/json' } }));
  // По одному, а не addAll: один недоступный файл не должен отменять
  // остальные. Уже лежащее в кеше не качается заново — хеш в имени.
  for (const file of files) {
    const url = new URL(file, self.location.origin + '/').href;
    if (await cache.match(url)) continue;
    try {
      const r = await fetch(url);
      if (r.ok) await cache.put(url, r);
    } catch {
      // нет сети — догрузится при использовании
    }
  }
}

// Файлы прошлых сборок (их имён нет в текущем precache.json) удаляются —
// иначе кеш рос бы с каждой выкладкой.
async function pruneOldAssets() {
  const cache = await caches.open(CACHE_NAME);
  const manifest = await cache.match('./precache.json');
  if (!manifest) return;
  const { files } = await manifest.json();
  const keep = new Set(files.map((f) => new URL(f, self.location.origin + '/').href));
  for (const req of await cache.keys()) {
    const { pathname } = new URL(req.url);
    if (pathname.startsWith('/assets/') && !keep.has(req.url)) await cache.delete(req);
  }
}

async function trimMediaCache() {
  const cache = await caches.open(MEDIA_CACHE);
  const keys = await cache.keys();
  // keys() — в порядке добавления: удаляются самые старые.
  for (let i = 0; i < keys.length - MEDIA_CACHE_LIMIT; i++) await cache.delete(keys[i]);
}

async function mediaResponse(request) {
  const cache = await caches.open(MEDIA_CACHE);
  const cached = await cache.match(request.url);
  if (cached) return cached;
  try {
    const response = await fetch(request.url, { mode: 'cors', credentials: 'omit' });
    if (response.ok) {
      await cache.put(request.url, response.clone());
      trimMediaCache().catch(() => {});
    }
    return response;
  } catch {
    // CORS не прошёл или нет сети — как обычный запрос браузера, без кеша.
    return fetch(request);
  }
}

self.addEventListener('install', (event) => {
  event.waitUntil(precache().catch(() => {}));
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE_NAME && key !== MEDIA_CACHE).map((key) => caches.delete(key))))
      .then(() => pruneOldAssets().catch(() => {}))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;

  // Only handle simple GETs. Everything else (API and AI calls, Google
  // Fonts, any non-GET request) passes straight through to the network
  // untouched — those inherently need connectivity and shouldn't be cached
  // or faked.
  if (request.method !== 'GET') return;
  const url = new URL(request.url);

  if (url.origin !== self.location.origin) {
    if (request.destination === 'image' && MEDIA_HOSTS.test(url.hostname)) {
      event.respondWith(mediaResponse(request));
    }
    return;
  }
  // /s/<token> на этом же домене отвечает не GitHub Pages, а воркер превью
  // общей ссылки (cloudflare-backend/share-preview.js) — страница-переходник
  // в приложение. Кешировать её незачем: каждый токен осел бы в кеше
  // навсегда, а удалённый план продолжал бы «открываться» из него.
  if (url.pathname.startsWith('/s/')) return;

  // Сама страница — сначала сеть, кеш только без связи. Раньше и она шла
  // «сначала из кеша»: после каждой выкладки первый заход получал старый
  // index.html, а он ссылался на бандл, которого на сервере уже нет
  // (публикация заменяет сайт целиком) — белый экран или «Failed to fetch
  // dynamically imported module», пока человек не перезагрузит ещё раз.
  // no-cache — чтобы и HTTP-кеш браузера не подсунул старую страницу.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(new Request(url.href, { cache: 'no-cache', credentials: 'same-origin' }))
        .then((response) => {
          if (response && response.ok) {
            const copy = response.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put('./index.html', copy)).catch(() => {});
          }
          return response;
        })
        .catch(() => caches.match('./index.html').then((cached) => cached || caches.match('./')))
    );
    return;
  }

  // Бандлы сборки (/assets/, хеш в имени) под тем же адресом не меняются
  // никогда — из кеша, без фоновой перепроверки. Раньше каждый запуск
  // заново скачивал в фоне все использованные файлы (~1,6 МБ на каждое
  // открытие приложения), хотя ни один из них не мог измениться.
  if (url.pathname.startsWith('/assets/')) {
    event.respondWith(
      caches.match(request).then((cached) => cached || fetch(request).then((response) => {
        if (response && response.ok) {
          const copy = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, copy)).catch(() => {});
        }
        return response;
      }))
    );
    return;
  }

  // Остальное (иконки, манифест, текстуры глобуса — без хеша в имени) —
  // из кеша сразу, обновление в фоне.
  event.respondWith(
    caches.match(request).then((cached) => {
      const network = fetch(request)
        .then((response) => {
          if (response && response.ok) {
            const copy = response.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(request, copy)).catch(() => {});
          }
          return response;
        })
        .catch(() => cached);
      // Serve from cache immediately when we have it (fast, and works
      // offline); refresh the cache in the background for next time.
      return cached || network;
    })
  );
});
